import logging
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ProvidedContent(object):
    detectable_hardware = (
        "basebandModules",
        "systemModules",
        "cabinets",
        "cables",
        "gnsse",
        "gnssi",
        "powerModules",
        "radioModules",
        "transportModules"
    )
    software_information = "swInfo"
    baseband_modules_information = "basebandModules"
    cells_information = "cells"
    gnsse_information = 'gnsse'
    active_alarms = 'currentAlarms'
    historic_alarms = 'historicalAlarms'
    system_modules_information = "systemModules"
    radio_modules_information = "radioModules"
    rmod_information = 'rmod'
    asirmod_information = 'asirmod'
    cabinets_information = 'cabinets'
    fan_status_locations = {
        "RMOD": (radio_modules_information, "rmod")
    }
    request_message = 'requestMessage'


class AdminConnection(Facade4GLegacy):
    """

    """
    _api_client = None

    def __init__(self,
                 bts_host="192.168.255.1",
                 bts_port=443,
                 username="Nemuadmin",
                 password="nemuuser",
                 use_ssl=True,
                 update_interval=5000,
                 admin_api_log_dir="",
                 name="default",
                 log_level=None,
                 bundle_path=None,
                 reconnect_with_default_on_failure=False,
                 release="admin20a"
                 ):
        """
        :param str bts_host: BTS IP address.
        :param int bts_port: AdminAPI port.
        :param str username: AdminAPI username.
        :param str password: AdminAPI password.
        :param bool use_ssl: use SSL.
        :param int update_interval: The minimum updates interval in [ms].
        :param str admin_api_log_dir: AdminAPI log dir
        :param str name: (Optional) Name of returned connection. It not provided, this connection becomes default.
        :param int log_level: (Optional) Level of log messages send to StreamHandler (default to screen). It is based on
            logging levels from logging library - https://docs.python.org/3.7/library/logging.html#logging-levels
            Default is logging.ERROR, it is 40.
        :param str bundle_path: (Optional) Path to alternative or knife bundle.js provided by ADMIN
        :param bool reconnect_with_default_on_failure: (Optional): DEPRECATED, do not use.
        :param str release: Name of coam admin interface version. Set to the newest by default. Available releases:
            admin19b, admin20a
        """
        debug_log = path.join(admin_api_log_dir, "admin_api_{}.log".format(name))
        self._set_log_level(log_level)

        if reconnect_with_default_on_failure:
            logger.critical("DEPRECATED: 'reconnect_with_default_on_failure' "
                            "parameter no longer works, and will be removed in "
                            "the future release.")

        self._api_client = AdminApi(
            bts_host,
            bts_port,
            username,
            password,
            use_ssl,
            update_interval,
            debug_log,
            bundle_path,
            None,
            "ute",
            "Ute",
            30,
        )

        self._coam_admin_interface = CoamAdminProvider.get_coam_admin_interface(
            release=release,
            api_client=self._api_client
        )

    def _set_log_level(self, log_level):
        if log_level:
            enable_logging(log_level=log_level)

    def __del__(self):
        self.disconnect()

    def disconnect(self):
        """
        Disconnect api client.

        TODO: Catch teardown errors
        """
        try:
            self._coam_admin_interface.disconnect()
        except AttributeError:
            logging.info('Connection is already not available.')

    def get_bts_info(self, timeout=10):
        """
        Get overall information regarding Node B from M-Plane (OAM).

        :param int timeout: Timeout for the operation.
        :return dict: Dictionary structure with data, where Keys are various information categories.
                      More details (content of requestMessage is returned data):
                      https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-getBtsInformation.html
        """

        return self._coam_admin_interface.get_bts_info(timeout=timeout)

