    def get_cells_info(self, cell_type="nr", timeout=10):
        """
        Get information about all cells, provided by M-plane (OAM).
        Currently the returned structures are different for 5G(nr) and 4G.

        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" (5G). Default: "nr".
        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If cell or 5G (nr) cell data is not provided by M-Plane.
        :return list: List of dictionaries with data for each available cell of given type.
                      For 4G structure example see:
                       https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-getCellList.html


        Example based on current 5G implementation:

        ::

        [{u'band': u'n257',
          u'chBw': u'100MHz',
          u'nrarfcn': 2059000,
          u'physCellId': 50,
          u'technology': u'TDD'}]
        """

        return self._coam_admin_interface.get_cells_info(cell_type=cell_type, timeout=timeout)

